const EXPL = [{"id":"j_volatile","sec":"Java","lvl":"c","xl":1,"tab":"volatile","file":"Worker.java","code":["private volatile boolean running = true;","","// thread A","while (running) { traiter(); }","","// thread B","running = false;   // A le voit tout de suite","","volatile int count; count++; // PAS atomique"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Thread B","s":"écrit running = false","tf":"Thread B","sf":"écrit running = false","te":"Thread B","se":"writes running = false","at":1},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Mémoire principale","s":"valeur à jour","tf":"Mémoire principale","sf":"valeur à jour","te":"Main memory","se":"up-to-date value","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Thread A","s":"relit running","tf":"Thread A","sf":"relit running","te":"Thread A","se":"re-reads running","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"count++","s":"lire + écrire = 2 étapes","tf":"count++","sf":"lire + écrire = 2 étapes","te":"count++","se":"read + write = 2 steps","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":[],"txt":"Sans volatile, chaque thread peut garder une copie de running dans le cache de son cœur."},{"line":[6,7],"on":["n0","n1"],"txt":"Avec volatile, l'écriture du thread B part directement en mémoire principale."},{"line":[3,4],"on":["n1","n2"],"txt":"Le thread A relit la vraie valeur à chaque tour : la boucle s'arrête aussitôt."},{"line":[9],"on":[],"bad":["n3"],"txt":"Attention : volatile garantit la visibilité, pas l'atomicité. count++ peut perdre des incréments ; il faut AtomicInteger ou un verrou."}],"en":{"tab":"volatile","steps":["Without volatile, each thread may keep a copy of running in its core's cache.","With volatile, thread B's write goes straight to main memory.","Thread A reads the real value on every loop: it stops right away.","Careful: volatile guarantees visibility, not atomicity. count++ can lose increments; use AtomicInteger or a lock."]}},{"id":"j_atomic","sec":"Java","lvl":"c","xl":1,"tab":"AtomicInteger","file":"Compteur.java","code":["AtomicInteger vues = new AtomicInteger();","","// 100 threads en parallèle","vues.incrementAndGet();","","// en interne (CAS) :","do { v = get(); }","while (!compareAndSet(v, v + 1));"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Lire v","s":"ex. 41","tf":"Lire v","sf":"ex. 41","te":"Read v","se":"e.g. 41","at":1},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"compareAndSet(41, 42)","s":"vaut toujours 41 ?","tf":"compareAndSet(41, 42)","sf":"vaut toujours 41 ?","te":"compareAndSet(41, 42)","se":"still 41?","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Oui → 42","s":"écrit en une instruction","tf":"Oui → 42","sf":"écrit en une instruction","te":"Yes → 42","se":"written in one instruction","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Non → on recommence","s":"un autre thread est passé","tf":"Non → on recommence","sf":"un autre thread est passé","te":"No → retry","se":"another thread got there first","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":[],"txt":"Un int partagé incrémenté par plusieurs threads perd des valeurs : deux threads lisent 41 et écrivent tous les deux 42."},{"line":[7,8],"on":["n0","n1"],"txt":"AtomicInteger lit la valeur puis demande au processeur : « remplace 41 par 42 seulement si c'est encore 41 »."},{"line":[4],"on":["n2"],"txt":"Si personne n'a touché la valeur, l'écriture réussit : c'est le compare-and-swap (CAS), sans verrou."},{"line":[7,8],"on":[],"bad":["n3"],"txt":"Sinon on relit et on réessaie. Résultat : 100 incréments = +100, sans synchronized."}],"en":{"tab":"AtomicInteger","steps":["A shared int incremented by several threads loses values: two threads read 41 and both write 42.","AtomicInteger reads the value then asks the CPU: \"replace 41 with 42 only if it is still 41\".","If nobody touched it, the write succeeds: this is compare-and-swap (CAS), with no lock.","Otherwise it re-reads and retries. Result: 100 increments = +100, without synchronized."]}},{"id":"j_chm","sec":"Java","lvl":"c","xl":1,"tab":"ConcurrentHashMap","file":"Stats.java","code":["ConcurrentHashMap<String,Integer> vues = new ConcurrentHashMap<>();","","// ❌ deux opérations séparées","vues.put(page, vues.get(page) + 1);","","// ✅ atomique pour la clé","vues.merge(page, 1, Integer::sum);"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"get(page)","s":"lit 10","tf":"get(page)","sf":"lit 10","te":"get(page)","se":"reads 10","at":1},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"put(page, 11)","s":"un autre thread a écrit 11","tf":"put(page, 11)","sf":"un autre thread a écrit 11","te":"put(page, 11)","se":"another thread wrote 11","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"merge(page, 1, sum)","s":"verrou sur la clé seule","tf":"merge(page, 1, sum)","sf":"verrou sur la clé seule","te":"merge(page, 1, sum)","se":"locks that key only","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Résultat : 12","s":"aucune mise à jour perdue","tf":"Résultat : 12","sf":"aucune mise à jour perdue","te":"Result: 12","se":"no lost update","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":[],"txt":"ConcurrentHashMap protège chaque opération, mais pas l'enchaînement de deux opérations."},{"line":[3,4],"on":[],"bad":["n0","n1"],"txt":"get puis put : deux threads lisent 10 et écrivent 11. Une vue est perdue."},{"line":[6,7],"on":["n2"],"txt":"merge (ou compute) fait lecture et écriture d'un seul bloc, en verrouillant seulement cette clé."},{"line":[7],"on":["n2","n3"],"txt":"Les deux incréments sont comptés, et les autres clés restent accessibles en parallèle."}],"en":{"tab":"ConcurrentHashMap","steps":["ConcurrentHashMap protects each operation, but not a sequence of two operations.","get then put: two threads read 10 and write 11. One view is lost.","merge (or compute) reads and writes in one block, locking only that key.","Both increments are counted, and other keys stay accessible in parallel."]}},{"id":"j_cf","sec":"Java","lvl":"c","xl":1,"tab":"CompletableFuture","file":"CommandeService.java","code":["CompletableFuture<Client> client = chargerClient(id);","","// ❌ thenApply : future dans un future","client.thenApply(c -> chargerCommandes(c));","","// ✅ thenCompose : aplati","client.thenCompose(c -> chargerCommandes(c))","      .thenAccept(cmds -> afficher(cmds));"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"chargerClient(id)","s":"CompletableFuture<Client>","tf":"chargerClient(id)","sf":"CompletableFuture<Client>","te":"loadClient(id)","se":"CompletableFuture<Client>","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"thenApply","s":"Future<Future<List>>","tf":"thenApply","sf":"Future<Future<List>>","te":"thenApply","se":"Future<Future<List>>","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"thenCompose","s":"Future<List<Commande>>","tf":"thenCompose","sf":"Future<List<Commande>>","te":"thenCompose","se":"Future<List<Order>>","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"thenAccept","s":"afficher le résultat","tf":"thenAccept","sf":"afficher le résultat","te":"thenAccept","se":"display the result","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"chargerClient renvoie un CompletableFuture : le client arrivera plus tard, sans bloquer."},{"line":[3,4],"on":[],"bad":["n1"],"txt":"chargerCommandes renvoie lui aussi un future. Avec thenApply, on obtient un future imbriqué, pénible à utiliser."},{"line":[6,7],"on":["n0","n2"],"txt":"thenCompose enchaîne le deuxième appel asynchrone et aplatit le résultat, comme flatMap."},{"line":[8],"on":["n2","n3"],"txt":"On continue la chaîne normalement. Règle : la fonction renvoie un future → thenCompose ; une valeur simple → thenApply."}],"en":{"tab":"CompletableFuture","steps":["loadClient returns a CompletableFuture: the client will arrive later, without blocking.","loadOrders also returns a future. With thenApply you get a nested future, awkward to use.","thenCompose chains the second async call and flattens the result, like flatMap.","The chain continues normally. Rule: the function returns a future → thenCompose; a plain value → thenApply."]}},{"id":"j_gc","sec":"Java","lvl":"s","xl":1,"tab":"Garbage collector","file":"JVM.txt","code":["java -XX:+UseG1GC -Xmx2g -jar app.jar","","Tas découpé en régions :","[Eden][Eden][Survivor][Old][Old][Humongous]","","Pause cible : -XX:MaxGCPauseMillis=200","Java 9+ : G1 par défaut ; CMS supprimé (Java 14)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Tas en régions","s":"Eden, Survivor, Old","tf":"Tas en régions","sf":"Eden, Survivor, Old","te":"Heap in regions","se":"Eden, Survivor, Old","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Collecte jeune","s":"objets récents, rapide","tf":"Collecte jeune","sf":"objets récents, rapide","te":"Young collection","se":"recent objects, fast","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Régions les plus « sales »","s":"nettoyées en priorité","tf":"Régions les plus « sales »","sf":"nettoyées en priorité","te":"Dirtiest regions","se":"cleaned first","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Pauses courtes","s":"prévisibles","tf":"Pauses courtes","sf":"prévisibles","te":"Short pauses","se":"predictable","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[3,4],"on":["n0"],"txt":"G1 découpe le tas en petites régions au lieu de grandes zones fixes."},{"line":[4],"on":["n1"],"txt":"La plupart des objets meurent jeunes : G1 nettoie souvent l'Eden, c'est rapide."},{"line":[6],"on":["n2"],"txt":"Pour la vieille génération, il commence par les régions qui contiennent le plus de déchets (d'où « Garbage First »)."},{"line":[7],"on":["n3"],"txt":"Objectif : des pauses courtes et prévisibles. C'est le GC par défaut depuis Java 9 ; ZGC existe pour des pauses encore plus courtes."}],"en":{"tab":"Garbage collector","steps":["G1 splits the heap into small regions instead of large fixed areas.","Most objects die young: G1 often cleans Eden, which is fast.","For the old generation it starts with the regions holding the most garbage (hence \"Garbage First\").","Goal: short, predictable pauses. It is the default since Java 9; ZGC exists for even shorter pauses."]}},{"id":"j_leak","sec":"Java","lvl":"s","xl":1,"tab":"Fuite mémoire","file":"CacheClients.java","code":["class CacheClients {","  static Map<Long, Client> cache = new HashMap<>();","  Client get(long id) {","    return cache.computeIfAbsent(id, this::charger);","  }","}","// ✅ cache borné : Caffeine.newBuilder().maximumSize(10_000)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"static Map","s":"vit tant que l'appli tourne","tf":"static Map","sf":"vit tant que l'appli tourne","te":"static Map","se":"lives as long as the app","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Chaque client ajouté","s":"jamais retiré","tf":"Chaque client ajouté","sf":"jamais retiré","te":"Each client added","se":"never removed","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"GC","s":"ne libère que l'inaccessible","tf":"GC","sf":"ne libère que l'inaccessible","te":"GC","se":"only frees unreachable objects","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"OutOfMemoryError","s":"la mémoire sature","tf":"OutOfMemoryError","sf":"la mémoire sature","te":"OutOfMemoryError","se":"memory runs out","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Une collection static reste accessible pendant toute la vie de l'application."},{"line":[3,4],"on":["n1"],"txt":"Chaque appel ajoute un client, et rien ne les retire : la map grossit sans fin."},{"line":[4],"on":["n2"],"bad":["n3"],"txt":"Le GC ne libère que les objets inaccessibles. Ici, tous restent référencés : la mémoire monte jusqu'au OutOfMemoryError."},{"line":[7],"on":[],"txt":"Solutions : un cache borné avec expiration (Caffeine), retirer les listeners, et analyser un heap dump pour trouver le coupable."}],"en":{"tab":"Memory leak","steps":["A static collection stays reachable for the application's whole life.","Each call adds a client and nothing removes them: the map grows forever.","The GC only frees unreachable objects. Here all stay referenced: memory climbs until OutOfMemoryError.","Fixes: a bounded cache with expiry (Caffeine), remove listeners, and analyse a heap dump to find the culprit."]}},{"id":"j_vthreads","sec":"Java","lvl":"s","xl":1,"tab":"Threads virtuels","file":"Appels.java","code":["try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {","  for (int i = 0; i < 10_000; i++)","    ex.submit(() -> api.appelerFournisseur()); // attend le réseau","}","","// calcul pur : nombre de cœurs = limite"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"10 000 tâches","s":"appels HTTP","tf":"10 000 tâches","sf":"appels HTTP","te":"10,000 tasks","se":"HTTP calls","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Threads virtuels","s":"très légers","tf":"Threads virtuels","sf":"très légers","te":"Virtual threads","se":"very light","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Attente réseau","s":"libère le thread porteur","tf":"Attente réseau","sf":"libère le thread porteur","te":"Network wait","se":"frees the carrier thread","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Quelques threads OS","s":"font tout le travail","tf":"Quelques threads OS","sf":"font tout le travail","te":"A few OS threads","se":"do all the work","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[2,3],"on":["n0"],"txt":"Un thread classique coûte environ 1 Mo : 10 000 appels HTTP en parallèle épuisent la machine."},{"line":[1],"on":["n1"],"txt":"Java 21 crée un thread virtuel par tâche : quelques Ko chacun, on peut en avoir des millions."},{"line":[3],"on":["n2","n3"],"txt":"Quand une tâche attend le réseau, son thread virtuel se met de côté et libère le thread système pour une autre."},{"line":[6],"on":[],"txt":"Gros gain pour les E/S (HTTP, base de données). Pour du calcul pur, aucun gain : le nombre de cœurs reste la limite."}],"en":{"tab":"Virtual threads","steps":["A classic thread costs about 1 MB: 10,000 parallel HTTP calls exhaust the machine.","Java 21 creates one virtual thread per task: a few KB each, you can have millions.","When a task waits on the network, its virtual thread steps aside and frees the OS thread for another one.","Big win for I/O (HTTP, database). For pure computation, no gain: the number of cores is still the limit."]}},{"id":"j_records","sec":"Java","lvl":"c","xl":1,"tab":"Records","file":"Montant.java","code":["record Montant(BigDecimal valeur, String devise) {","  Montant {  // constructeur compact : validation","    if (valeur.signum() < 0) throw new IllegalArgumentException();","  }","}","var m = new Montant(new BigDecimal(\"10.50\"), \"TND\");","m.valeur();  // accesseur, pas getValeur()"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"record","s":"classe finale immuable","tf":"record","sf":"classe finale immuable","te":"record","se":"immutable final class","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Généré","s":"constructeur, accesseurs","tf":"Généré","sf":"constructeur, accesseurs","te":"Generated","se":"constructor, accessors","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Généré aussi","s":"equals, hashCode, toString","tf":"Généré aussi","sf":"equals, hashCode, toString","te":"Also generated","se":"equals, hashCode, toString","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Pas de setters","s":"valeurs figées","tf":"Pas de setters","sf":"valeurs figées","te":"No setters","se":"values are fixed","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Un record déclare ses champs dans l'en-tête : ils deviennent private final."},{"line":[6,7],"on":["n1"],"txt":"Java génère le constructeur et les accesseurs valeur() et devise()."},{"line":[1],"on":["n2"],"txt":"equals, hashCode et toString sont générés à partir des champs : idéal pour des DTO et des valeurs."},{"line":[2,3,4],"on":["n3"],"txt":"Pas de setters : pour valider, on utilise le constructeur compact. Un record ne convient pas comme entité JPA (il faut un objet modifiable)."}],"en":{"tab":"Records","steps":["A record declares its fields in the header: they become private final.","Java generates the constructor and the accessors valeur() and devise().","equals, hashCode and toString are generated from the fields: ideal for DTOs and value objects.","No setters: validate in the compact constructor. A record is not suited as a JPA entity (which must be mutable)."]}},{"id":"j_parallel","sec":"Java","lvl":"s","xl":1,"tab":"Streams parallèles","file":"RapportService.java","code":["// ❌ dans un service web","factures.parallelStream()","        .map(f -> repo.chargerDetails(f))  // appel base, bloquant","        .toList();","","// ForkJoinPool commun : (cœurs - 1) threads pour TOUTE l'appli","// ✅ stream() simple, ou un executor dédié"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"parallelStream()","s":"découpe le travail","tf":"parallelStream()","sf":"découpe le travail","te":"parallelStream()","se":"splits the work","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"ForkJoinPool commun","s":"partagé par toute l'appli","tf":"ForkJoinPool commun","sf":"partagé par toute l'appli","te":"Common ForkJoinPool","se":"shared by the whole app","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Appels bloquants","s":"threads occupés à attendre","tf":"Appels bloquants","sf":"threads occupés à attendre","te":"Blocking calls","se":"threads busy waiting","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Autres requêtes","s":"bloquées aussi","tf":"Autres requêtes","sf":"bloquées aussi","te":"Other requests","se":"blocked too","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[2],"on":["n0"],"txt":"parallelStream découpe la liste et traite les morceaux en parallèle."},{"line":[6],"on":["n1"],"txt":"Mais il utilise le ForkJoinPool commun : peu de threads, partagés par tout le code de l'application."},{"line":[3],"on":[],"bad":["n2","n3"],"txt":"Des appels base de données bloquent ces threads : les autres parallelStream de l'appli attendent aussi."},{"line":[7],"on":[],"txt":"À réserver au calcul pur sur de gros volumes. Pour des E/S : stream() simple, un executor dédié ou des threads virtuels."}],"en":{"tab":"Parallel streams","steps":["parallelStream splits the list and processes the chunks in parallel.","But it uses the common ForkJoinPool: few threads, shared by all the application's code.","Database calls block those threads: every other parallel stream in the app waits too.","Keep it for pure computation on large data. For I/O: plain stream(), a dedicated executor or virtual threads."]}},{"id":"s_selfcall","sec":"Spring Boot","lvl":"c","xl":1,"tab":"Appel interne @Transactional","file":"FactureService.java","code":["@Service class FactureService {","  public void importer(List<Facture> l) {","    l.forEach(this::enregistrer);   // ❌ appel interne","  }","  @Transactional public void enregistrer(Facture f) { ... }","}","// ✅ mettre enregistrer() dans un autre bean"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Contrôleur","s":"appelle importer()","tf":"Contrôleur","sf":"appelle importer()","te":"Controller","se":"calls importer()","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Proxy Spring","s":"gère @Transactional","tf":"Proxy Spring","sf":"gère @Transactional","te":"Spring proxy","se":"handles @Transactional","at":0},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"importer()","s":"dans le vrai objet","tf":"importer()","sf":"dans le vrai objet","te":"importer()","se":"inside the real object","at":1},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"this.enregistrer()","s":"contourne le proxy","tf":"this.enregistrer()","sf":"contourne le proxy","te":"this.enregistrer()","se":"bypasses the proxy","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":0},{"id":"e1","d":"M180 136V158","at":1},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1],"on":["n0","n1"],"txt":"Spring entoure le bean d'un proxy : c'est lui qui ouvre et valide la transaction."},{"line":[2],"on":["n1","n2"],"txt":"Le contrôleur appelle importer() via le proxy, puis on entre dans le vrai objet."},{"line":[3,5],"on":[],"bad":["n3"],"txt":"importer() appelle this.enregistrer() : l'appel ne repasse pas par le proxy, donc @Transactional est ignoré."},{"line":[7],"on":[],"txt":"Solution : placer la méthode transactionnelle dans un autre bean, ou mettre @Transactional sur la méthode appelée de l'extérieur."}],"en":{"tab":"@Transactional self-call","steps":["Spring wraps the bean in a proxy: it opens and commits the transaction.","The controller calls importer() through the proxy, then enters the real object.","importer() calls this.enregistrer(): the call does not go back through the proxy, so @Transactional is ignored.","Fix: move the transactional method to another bean, or put @Transactional on the method called from outside."]}},{"id":"s_rollback","sec":"Spring Boot","lvl":"c","xl":1,"tab":"Rollback","file":"PaiementService.java","code":["@Transactional","public void payer(Commande c) throws IOException {","  repo.save(paiement);","  banque.envoyer(c);   // lève IOException (vérifiée)","}","// IOException → COMMIT par défaut !","@Transactional(rollbackFor = Exception.class)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"save(paiement)","s":"dans la transaction","tf":"save(paiement)","sf":"dans la transaction","te":"save(payment)","se":"inside the transaction","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"RuntimeException","s":"→ rollback","tf":"RuntimeException","sf":"→ rollback","te":"RuntimeException","se":"→ rollback","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Exception vérifiée","s":"→ commit","tf":"Exception vérifiée","sf":"→ commit","te":"Checked exception","se":"→ commit","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"rollbackFor","s":"→ rollback aussi","tf":"rollbackFor","sf":"→ rollback aussi","te":"rollbackFor","se":"→ rollback too","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[3],"on":["n0"],"txt":"Le paiement est enregistré dans la transaction."},{"line":[1],"on":["n1"],"txt":"Si une RuntimeException (ou une Error) sort de la méthode, Spring annule tout : c'est le comportement par défaut."},{"line":[4,6],"on":[],"bad":["n2"],"txt":"Mais une exception vérifiée comme IOException valide la transaction : le paiement reste en base alors que l'envoi a échoué."},{"line":[7],"on":["n3"],"txt":"rollbackFor = Exception.class force le rollback pour les exceptions vérifiées aussi."}],"en":{"tab":"Rollback","steps":["The payment is saved inside the transaction.","If a RuntimeException (or an Error) leaves the method, Spring rolls everything back: that is the default.","But a checked exception like IOException commits: the payment stays in the database although sending failed.","rollbackFor = Exception.class forces a rollback for checked exceptions too."]}},{"id":"s_cache","sec":"Spring Boot","lvl":"c","xl":1,"tab":"@Cacheable","file":"ClientService.java","code":["@Cacheable(\"clients\")","public Client findById(Long id) {","  return repo.findById(id).orElseThrow();  // requête SQL","}","@CacheEvict(value = \"clients\", key = \"#c.id\")","public void modifier(Client c) { repo.save(c); }"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"findById(7)","s":"1er appel","tf":"findById(7)","sf":"1er appel","te":"findById(7)","se":"1st call","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Base de données","s":"requête SQL","tf":"Base de données","sf":"requête SQL","te":"Database","se":"SQL query","at":0},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Cache « clients »","s":"7 → Client","tf":"Cache « clients »","sf":"7 → Client","te":"\"clients\" cache","se":"7 → Client","at":1},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"findById(7)","s":"appels suivants : cache","tf":"findById(7)","sf":"appels suivants : cache","te":"findById(7)","se":"next calls: cache","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":0},{"id":"e1","d":"M180 136V158","at":1},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[2,3],"on":["n0","n1"],"txt":"Premier appel : la méthode s'exécute et interroge la base."},{"line":[1],"on":["n2"],"txt":"Le résultat est rangé dans le cache « clients » sous la clé 7."},{"line":[1,2],"on":["n2","n3"],"txt":"Appels suivants avec 7 : Spring renvoie la valeur du cache sans exécuter la méthode, donc sans SQL."},{"line":[5,6],"on":[],"txt":"Quand le client change, @CacheEvict retire l'entrée pour ne pas servir une donnée périmée. Ne pas oublier @EnableCaching."}],"en":{"tab":"@Cacheable","steps":["First call: the method runs and queries the database.","The result is stored in the \"clients\" cache under key 7.","Next calls with 7: Spring returns the cached value without running the method, so no SQL.","When the client changes, @CacheEvict removes the entry so stale data is not served. Don't forget @EnableCaching."]}},{"id":"s_async","sec":"Spring Boot","lvl":"c","xl":1,"tab":"@Async","file":"MailService.java","code":["@EnableAsync @SpringBootApplication class App {}","","@Service class MailService {","  @Async public CompletableFuture<Void> envoyer(Mail m) { ... }","}","// appelé depuis un AUTRE bean :","mailService.envoyer(m);   // ne bloque pas la requête"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"@EnableAsync","s":"active la fonctionnalité","tf":"@EnableAsync","sf":"active la fonctionnalité","te":"@EnableAsync","se":"turns the feature on","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Contrôleur","s":"appelle mailService","tf":"Contrôleur","sf":"appelle mailService","te":"Controller","se":"calls mailService","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Proxy","s":"envoie dans un pool","tf":"Proxy","sf":"envoie dans un pool","te":"Proxy","se":"hands off to a pool","at":1},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Thread du pool","s":"envoie le mail","tf":"Thread du pool","sf":"envoie le mail","te":"Pool thread","se":"sends the mail","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":1},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1],"on":["n0"],"txt":"Sans @EnableAsync, @Async est ignoré et la méthode s'exécute normalement."},{"line":[6,7],"on":["n1","n2"],"txt":"L'appel venant d'un autre bean passe par le proxy, qui confie la méthode à un pool de threads."},{"line":[4],"on":["n3"],"txt":"La requête HTTP se termine tout de suite ; le mail part en arrière-plan."},{"line":[4],"on":[],"txt":"Comme @Transactional, un appel interne (this.envoyer) contourne le proxy. On renvoie void ou CompletableFuture pour suivre le résultat."}],"en":{"tab":"@Async","steps":["Without @EnableAsync, @Async is ignored and the method runs normally.","The call from another bean goes through the proxy, which hands the method to a thread pool.","The HTTP request ends at once; the mail is sent in the background.","Like @Transactional, an internal call (this.envoyer) bypasses the proxy. Return void or CompletableFuture to track the result."]}},{"id":"s_refresh","sec":"Spring Boot","lvl":"s","xl":1,"tab":"Refresh token","file":"AuthController.java","code":["POST /auth/login    → accessToken (15 min) + refreshToken (7 j)","GET  /api/factures  Authorization: Bearer <accessToken>","","// accessToken expiré → 401","POST /auth/refresh  { refreshToken } → nouveau accessToken","","// déconnexion : refreshToken révoqué en base"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Connexion","s":"mot de passe une fois","tf":"Connexion","sf":"mot de passe une fois","te":"Login","se":"password once","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Access token","s":"15 min, non stocké","tf":"Access token","sf":"15 min, non stocké","te":"Access token","se":"15 min, not stored","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Refresh token","s":"stocké, révocable","tf":"Refresh token","sf":"stocké, révocable","te":"Refresh token","se":"stored, revocable","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Nouvel access token","s":"sans mot de passe","tf":"Nouvel access token","sf":"sans mot de passe","te":"New access token","se":"no password needed","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1],"on":["n0"],"txt":"À la connexion, le serveur renvoie deux jetons."},{"line":[2],"on":["n1"],"txt":"L'access token JWT accompagne chaque appel. Il n'est pas stocké côté serveur, donc difficile à révoquer : on le garde court."},{"line":[4,5],"on":["n2","n3"],"txt":"Quand il expire, le client envoie le refresh token et reçoit un nouvel access token, sans redemander le mot de passe."},{"line":[7],"on":["n2"],"txt":"Le refresh token est enregistré en base : à la déconnexion ou en cas de vol, on le révoque. Un token volé ne sert que 15 minutes."}],"en":{"tab":"Refresh token","steps":["At login, the server returns two tokens.","The JWT access token goes with every call. It is not stored server-side, so hard to revoke: keep it short.","When it expires, the client sends the refresh token and gets a new access token, without asking for the password.","The refresh token is stored in the database: on logout or theft, revoke it. A stolen access token only works for 15 minutes."]}},{"id":"s_circuit","sec":"Spring Boot","lvl":"s","xl":1,"tab":"Circuit breaker","file":"FournisseurClient.java","code":["@CircuitBreaker(name = \"stock\", fallbackMethod = \"stockParDefaut\")","public Stock lire(Long id) { return http.get(\"/stock/\" + id); }","","Stock stockParDefaut(Long id, Throwable t) { return Stock.inconnu(); }","","// fermé → (trop d'échecs) → ouvert → (attente) → semi-ouvert"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Fermé","s":"les appels passent","tf":"Fermé","sf":"les appels passent","te":"Closed","se":"calls go through","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Trop d'échecs","s":"ex. 50 % sur 10 appels","tf":"Trop d'échecs","sf":"ex. 50 % sur 10 appels","te":"Too many failures","se":"e.g. 50% of 10 calls","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Ouvert","s":"fallback immédiat","tf":"Ouvert","sf":"fallback immédiat","te":"Open","se":"immediate fallback","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Semi-ouvert","s":"quelques appels de test","tf":"Semi-ouvert","sf":"quelques appels de test","te":"Half-open","se":"a few test calls","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[2],"on":["n0"],"txt":"En temps normal, le circuit est fermé : chaque appel part vers le service de stock."},{"line":[2],"on":[],"bad":["n1"],"txt":"Le service devient lent ou en erreur : le taux d'échec dépasse le seuil."},{"line":[1,4],"on":["n2"],"txt":"Le circuit s'ouvre : les appels échouent tout de suite et renvoient le fallback, sans attendre ni surcharger le service."},{"line":[6],"on":["n3","n0"],"txt":"Après un délai, quelques appels de test passent. S'ils réussissent, le circuit se referme."}],"en":{"tab":"Circuit breaker","steps":["Normally the circuit is closed: every call goes to the stock service.","The service becomes slow or failing: the failure rate crosses the threshold.","The circuit opens: calls fail fast and return the fallback, without waiting or overloading the service.","After a delay, a few test calls go through. If they succeed, the circuit closes again."]}},{"id":"s_idem","sec":"Spring Boot","lvl":"s","xl":1,"tab":"Idempotence","file":"PaiementController.java","code":["POST /paiements","Idempotency-Key: 8f3a-…   (générée par le client)","","if (cles.existe(key)) return cles.resultat(key);  // déjà traité","Paiement p = service.payer(demande);","cles.enregistrer(key, p);","return p;"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"POST + clé","s":"1er envoi","tf":"POST + clé","sf":"1er envoi","te":"POST + key","se":"1st send","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Paiement traité","s":"clé enregistrée","tf":"Paiement traité","sf":"clé enregistrée","te":"Payment processed","se":"key stored","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Timeout","s":"le client renvoie","tf":"Timeout","sf":"le client renvoie","te":"Timeout","se":"the client resends","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Même clé","s":"même résultat, pas de doublon","tf":"Même clé","sf":"même résultat, pas de doublon","te":"Same key","se":"same result, no duplicate","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Le client génère une clé unique et l'envoie avec le paiement."},{"line":[5,6],"on":["n1"],"txt":"Le serveur traite le paiement et mémorise la clé avec le résultat."},{"line":[1],"on":["n2"],"txt":"La réponse se perd (timeout) : le client renvoie exactement la même requête."},{"line":[4],"on":["n3"],"txt":"Le serveur reconnaît la clé et renvoie le résultat déjà produit : un seul débit. C'est l'idempotence."}],"en":{"tab":"Idempotency","steps":["The client generates a unique key and sends it with the payment.","The server processes the payment and stores the key with the result.","The response gets lost (timeout): the client resends exactly the same request.","The server recognises the key and returns the result already produced: one charge only. That is idempotency."]}},{"id":"s_outbox","sec":"Spring Boot","lvl":"s","xl":1,"tab":"Pattern outbox","file":"CommandeService.java","code":["@Transactional","public void creer(Commande c) {","  commandes.save(c);","  outbox.save(new Evenement(\"CommandeCreee\", c.getId()));","}   // un seul COMMIT","","// relais (planifié) : lit outbox → publie sur Kafka → marque envoyé"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"save(commande)","s":"table commandes","tf":"save(commande)","sf":"table commandes","te":"save(order)","se":"orders table","at":1},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"save(événement)","s":"table outbox","tf":"save(événement)","sf":"table outbox","te":"save(event)","se":"outbox table","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"COMMIT","s":"les deux ou aucun","tf":"COMMIT","sf":"les deux ou aucun","te":"COMMIT","se":"both or neither","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Relais","s":"publie sur Kafka","tf":"Relais","sf":"publie sur Kafka","te":"Relay","se":"publishes to Kafka","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":[],"txt":"Problème : la base et Kafka n'ont pas de transaction commune. Publier avant ou après le commit peut perdre un message."},{"line":[3,4],"on":["n0","n1"],"txt":"On écrit la commande ET l'événement dans la même base, dans la même transaction."},{"line":[5],"on":["n2"],"txt":"Un seul commit : soit les deux sont enregistrés, soit aucun."},{"line":[7],"on":["n3"],"txt":"Un relais lit la table outbox et publie sur Kafka, en réessayant si besoin. Les consommateurs doivent tolérer un doublon."}],"en":{"tab":"Outbox pattern","steps":["Problem: the database and Kafka share no transaction. Publishing before or after the commit can lose a message.","Write the order AND the event to the same database, in the same transaction.","One commit: either both are saved or neither.","A relay reads the outbox table and publishes to Kafka, retrying if needed. Consumers must tolerate a duplicate."]}},{"id":"p_entitygraph","sec":"JPA / Hibernate","lvl":"c","xl":1,"tab":"@EntityGraph","file":"FactureRepository.java","code":["@EntityGraph(attributePaths = \"lignes\")","List<Facture> findByClientId(Long clientId);","","// SQL : select f.*, l.* from facture f","//       left join ligne l on l.facture_id = f.id","//       where f.client_id = ?"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"findByClientId","s":"50 factures","tf":"findByClientId","sf":"50 factures","te":"findByClientId","se":"50 invoices","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Sans graphe","s":"1 + 50 requêtes","tf":"Sans graphe","sf":"1 + 50 requêtes","te":"Without graph","se":"1 + 50 queries","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Avec @EntityGraph","s":"1 requête avec jointure","tf":"Avec @EntityGraph","sf":"1 requête avec jointure","te":"With @EntityGraph","se":"1 query with a join","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Ailleurs","s":"lignes reste LAZY","tf":"Ailleurs","sf":"lignes reste LAZY","te":"Elsewhere","se":"lines stays LAZY","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[2],"on":["n0"],"txt":"On charge les factures d'un client, puis on affiche leurs lignes."},{"line":[2],"on":[],"bad":["n1"],"txt":"Sans rien, chaque accès à facture.getLignes() déclenche une requête : c'est le problème N+1."},{"line":[1,4,5,6],"on":["n2"],"txt":"@EntityGraph ajoute une jointure pour cette méthode : factures et lignes arrivent en une seule requête."},{"line":[1],"on":["n3"],"txt":"La relation reste LAZY partout ailleurs : on charge le graphe seulement là où on en a besoin."}],"en":{"tab":"@EntityGraph","steps":["We load a client's invoices, then display their lines.","With nothing, each access to invoice.getLines() fires a query: the N+1 problem.","@EntityGraph adds a join for this method: invoices and lines arrive in one query.","The relation stays LAZY everywhere else: the graph is loaded only where needed."]}},{"id":"p_pessimistic","sec":"JPA / Hibernate","lvl":"s","xl":1,"tab":"Verrou pessimiste","file":"ArticleRepository.java","code":["@Lock(LockModeType.PESSIMISTIC_WRITE)","@Query(\"select a from Article a where a.id = :id\")","Article verrouiller(Long id);   // SELECT ... FOR UPDATE","","@Transactional void reserver(Long id) {","  Article a = repo.verrouiller(id);","  if (a.getStock() > 0) a.setStock(a.getStock() - 1);","}"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Utilisateur A","s":"verrouille la ligne","tf":"Utilisateur A","sf":"verrouille la ligne","te":"User A","se":"locks the row","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Utilisateur B","s":"attend","tf":"Utilisateur B","sf":"attend","te":"User B","se":"waits","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"A : stock 1 → 0","s":"commit, verrou libéré","tf":"A : stock 1 → 0","sf":"commit, verrou libéré","te":"A: stock 1 → 0","se":"commit, lock released","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"B relit","s":"stock 0 : refusé","tf":"B relit","sf":"stock 0 : refusé","te":"B re-reads","se":"stock 0: refused","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,3,6],"on":["n0"],"txt":"A lit l'article avec SELECT … FOR UPDATE : la ligne est verrouillée en base."},{"line":[6],"on":[],"bad":["n1"],"txt":"B veut le même article : sa requête attend la fin de la transaction de A."},{"line":[7],"on":["n2"],"txt":"A décrémente le stock et valide : le verrou est libéré."},{"line":[7],"on":["n3"],"txt":"B lit alors le stock à jour (0) et ne survend pas. Le verrou optimiste (@Version) laisse passer et détecte le conflit au commit, sans attente."}],"en":{"tab":"Pessimistic lock","steps":["A reads the item with SELECT … FOR UPDATE: the row is locked in the database.","B wants the same item: its query waits for A's transaction to end.","A decrements the stock and commits: the lock is released.","B then reads the fresh stock (0) and does not oversell. The optimistic lock (@Version) lets it through and detects the conflict at commit, without waiting."]}},{"id":"p_batch","sec":"JPA / Hibernate","lvl":"s","xl":1,"tab":"Insertions en masse","file":"application.properties","code":["spring.jpa.properties.hibernate.jdbc.batch_size=50","spring.jpa.properties.hibernate.order_inserts=true","","for (int i = 0; i < lignes.size(); i++) {","  em.persist(lignes.get(i));","  if (i % 50 == 0) { em.flush(); em.clear(); }","}","// id en SEQUENCE (IDENTITY désactive le batch)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"persist() x 100 000","s":"dans une transaction","tf":"persist() x 100 000","sf":"dans une transaction","te":"persist() x 100,000","se":"in one transaction","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"batch_size = 50","s":"50 INSERT par aller-retour","tf":"batch_size = 50","sf":"50 INSERT par aller-retour","te":"batch_size = 50","se":"50 INSERTs per round trip","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"flush() + clear()","s":"vide la mémoire","tf":"flush() + clear()","sf":"vide la mémoire","te":"flush() + clear()","se":"frees memory","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"ids SEQUENCE","s":"batch possible","tf":"ids SEQUENCE","sf":"batch possible","te":"SEQUENCE ids","se":"batching possible","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[4,5],"on":["n0"],"txt":"Sans réglage, Hibernate envoie un INSERT à la fois et garde les 100 000 entités en mémoire."},{"line":[1,2],"on":["n1"],"txt":"batch_size regroupe les INSERT par paquets de 50 : 50 fois moins d'allers-retours avec la base."},{"line":[6],"on":["n2"],"txt":"Tous les 50 éléments, flush() envoie le paquet et clear() vide le contexte de persistance : la mémoire reste stable."},{"line":[8],"on":["n3"],"txt":"Avec des id IDENTITY, Hibernate doit faire chaque INSERT pour connaître l'id : il désactive le batch. On utilise SEQUENCE."}],"en":{"tab":"Bulk inserts","steps":["Without tuning, Hibernate sends one INSERT at a time and keeps all 100,000 entities in memory.","batch_size groups INSERTs in packs of 50: 50 times fewer round trips to the database.","Every 50 items, flush() sends the pack and clear() empties the persistence context: memory stays stable.","With IDENTITY ids, Hibernate must run each INSERT to learn the id, so it disables batching. Use SEQUENCE."]}},{"id":"p_l2cache","sec":"JPA / Hibernate","lvl":"s","xl":1,"tab":"Cache de second niveau","file":"Pays.java","code":["@Entity @Cacheable","@org.hibernate.annotations.Cache(usage = READ_ONLY)","class Pays { @Id String code; String nom; }","","spring.jpa.properties.hibernate.cache.use_second_level_cache=true","// + un fournisseur : Ehcache, Caffeine (JCache)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Session 1","s":"1er niveau : sa mémoire","tf":"Session 1","sf":"1er niveau : sa mémoire","te":"Session 1","se":"1st level: its own memory","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Session 2","s":"ne voit pas la session 1","tf":"Session 2","sf":"ne voit pas la session 1","te":"Session 2","se":"cannot see session 1","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Cache 2e niveau","s":"partagé entre sessions","tf":"Cache 2e niveau","sf":"partagé entre sessions","te":"2nd-level cache","se":"shared across sessions","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Base de données","s":"moins sollicitée","tf":"Base de données","sf":"moins sollicitée","te":"Database","se":"queried less","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[3],"on":["n0"],"txt":"Le cache de 1er niveau est le contexte de persistance : il vit le temps d'une session (d'une transaction)."},{"line":[3],"on":[],"bad":["n1"],"txt":"Une autre session ne profite pas de ce cache : elle relit la base."},{"line":[1,2,5,6],"on":["n2"],"txt":"Le cache de 2e niveau, optionnel, est partagé par toutes les sessions. On l'active entité par entité."},{"line":[2],"on":["n2","n3"],"txt":"Idéal pour des données lues souvent et rarement modifiées (pays, taux de TVA). À éviter pour des données qui changent sans cesse."}],"en":{"tab":"Second-level cache","steps":["The first-level cache is the persistence context: it lives for one session (one transaction).","Another session does not benefit from it: it reads the database again.","The second-level cache, optional, is shared by all sessions. It is enabled entity by entity.","Ideal for data read often and rarely changed (countries, VAT rates). Avoid it for constantly changing data."]}},{"id":"p_dirty","sec":"JPA / Hibernate","lvl":"c","xl":1,"tab":"Dirty checking","file":"ClientService.java","code":["@Transactional","public void renommer(Long id, String nom) {","  Client c = repo.findById(id).orElseThrow();  // entité gérée","  c.setNom(nom);","  // pas de save()","}  // flush au commit → UPDATE client set nom = ? where id = ?"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"findById","s":"entité gérée","tf":"findById","sf":"entité gérée","te":"findById","se":"managed entity","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Copie de l'état","s":"gardée par Hibernate","tf":"Copie de l'état","sf":"gardée par Hibernate","te":"State snapshot","se":"kept by Hibernate","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"setNom()","s":"l'objet change","tf":"setNom()","sf":"l'objet change","te":"setNom()","se":"the object changes","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Commit","s":"comparaison → UPDATE","tf":"Commit","sf":"comparaison → UPDATE","te":"Commit","se":"comparison → UPDATE","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[3],"on":["n0"],"txt":"Dans une transaction, findById renvoie une entité « gérée » par le contexte de persistance."},{"line":[3],"on":["n1"],"txt":"Hibernate garde une copie de son état d'origine."},{"line":[4,5],"on":["n2"],"txt":"On modifie le nom sans appeler save()."},{"line":[6],"on":["n3"],"txt":"Au flush (au commit), Hibernate compare l'objet à sa copie, voit la différence et génère l'UPDATE tout seul : c'est le dirty checking."}],"en":{"tab":"Dirty checking","steps":["Inside a transaction, findById returns an entity \"managed\" by the persistence context.","Hibernate keeps a copy of its original state.","We change the name without calling save().","At flush (commit), Hibernate compares the object with its copy, sees the change and generates the UPDATE itself: dirty checking."]}},{"id":"q_explain","sec":"SQL / PostgreSQL","lvl":"c","xl":1,"tab":"EXPLAIN ANALYZE","file":"requete.sql","code":["EXPLAIN ANALYZE","SELECT * FROM facture WHERE client_id = 42;","","-- Seq Scan on facture (rows=2 000 000)  time=850 ms","CREATE INDEX idx_facture_client ON facture(client_id);","-- Index Scan using idx_facture_client (rows=37)  time=0.4 ms"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"EXPLAIN ANALYZE","s":"exécute et mesure","tf":"EXPLAIN ANALYZE","sf":"exécute et mesure","te":"EXPLAIN ANALYZE","se":"runs and measures","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Seq Scan","s":"lit 2 millions de lignes","tf":"Seq Scan","sf":"lit 2 millions de lignes","te":"Seq Scan","se":"reads 2 million rows","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"CREATE INDEX","s":"sur client_id","tf":"CREATE INDEX","sf":"sur client_id","te":"CREATE INDEX","se":"on client_id","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Index Scan","s":"va droit aux 37 lignes","tf":"Index Scan","sf":"va droit aux 37 lignes","te":"Index Scan","se":"goes straight to 37 rows","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2],"on":["n0"],"txt":"EXPLAIN ANALYZE exécute la requête et montre le plan choisi, avec le temps réel de chaque étape."},{"line":[4],"on":[],"bad":["n1"],"txt":"Seq Scan : PostgreSQL lit toute la table pour trouver 37 lignes. C'est le signe d'un index manquant."},{"line":[5],"on":["n2"],"txt":"On crée un index sur la colonne filtrée."},{"line":[6],"on":["n3"],"txt":"Le plan devient un Index Scan : 850 ms → 0,4 ms. Sur une petite table ou un filtre peu sélectif, le Seq Scan peut rester le meilleur choix."}],"en":{"tab":"EXPLAIN ANALYZE","steps":["EXPLAIN ANALYZE runs the query and shows the chosen plan, with the real time of each step.","Seq Scan: PostgreSQL reads the whole table to find 37 rows. A sign of a missing index.","Create an index on the filtered column.","The plan becomes an Index Scan: 850 ms → 0.4 ms. On a small table or an unselective filter, a Seq Scan can still be the best choice."]}},{"id":"q_composite","sec":"SQL / PostgreSQL","lvl":"c","xl":1,"tab":"Index composite","file":"index.sql","code":["CREATE INDEX idx ON facture(client_id, date_facture);","","WHERE client_id = 5                         -- ✅","WHERE client_id = 5 AND date_facture > ...  -- ✅","WHERE client_id = 5 ORDER BY date_facture   -- ✅ tri gratuit","WHERE date_facture > '2026-01-01'           -- ❌ pas la 1re colonne"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Index (client, date)","s":"trié par client puis date","tf":"Index (client, date)","sf":"trié par client puis date","te":"Index (client, date)","se":"sorted by client then date","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"client_id = 5","s":"on trouve le bloc du client","tf":"client_id = 5","sf":"on trouve le bloc du client","te":"client_id = 5","se":"finds the client's block","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"+ date","s":"déjà triée dans le bloc","tf":"+ date","sf":"déjà triée dans le bloc","te":"+ date","se":"already sorted in the block","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"date seule","s":"dispersée partout","tf":"date seule","sf":"dispersée partout","te":"date alone","se":"scattered everywhere","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Un index composite est trié comme un annuaire : d'abord par client, puis par date à l'intérieur de chaque client."},{"line":[3],"on":["n1"],"txt":"Filtrer sur client_id : on saute directement au bloc du client."},{"line":[4,5],"on":["n1","n2"],"txt":"Dans ce bloc, les dates sont déjà triées : filtre et ORDER BY sur la date sont rapides."},{"line":[6],"on":[],"bad":["n3"],"txt":"Sans client_id, les dates sont éparpillées dans tous les blocs : l'index ne sert pas. Mettre en premier la colonne la plus utilisée dans les filtres."}],"en":{"tab":"Composite index","steps":["A composite index is sorted like a phone book: first by client, then by date within each client.","Filter on client_id: jump straight to the client's block.","Inside that block, dates are already sorted: filtering and ORDER BY on the date are fast.","Without client_id, dates are scattered across all blocks: the index is useless. Put the most filtered column first."]}},{"id":"q_isolation","sec":"SQL / PostgreSQL","lvl":"s","xl":1,"tab":"Niveaux d'isolation","file":"transactions.sql","code":["-- PostgreSQL : READ COMMITTED par défaut","BEGIN;","SELECT solde FROM compte WHERE id = 1;   -- 100","-- une autre transaction valide : solde = 80","SELECT solde FROM compte WHERE id = 1;   -- 80","COMMIT;","-- REPEATABLE READ : on verrait 100 deux fois"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"READ COMMITTED","s":"défaut PostgreSQL","tf":"READ COMMITTED","sf":"défaut PostgreSQL","te":"READ COMMITTED","se":"PostgreSQL default","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"1re lecture","s":"100","tf":"1re lecture","sf":"100","te":"1st read","se":"100","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Autre transaction","s":"valide 80","tf":"Autre transaction","sf":"valide 80","te":"Other transaction","se":"commits 80","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"2e lecture","s":"80 (donnée validée)","tf":"2e lecture","sf":"80 (donnée validée)","te":"2nd read","se":"80 (committed data)","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"PostgreSQL utilise READ COMMITTED par défaut : on ne voit jamais de données non validées."},{"line":[2,3],"on":["n1"],"txt":"Première lecture du solde dans la transaction : 100."},{"line":[4],"on":["n2"],"txt":"Pendant ce temps, une autre transaction modifie le solde et valide."},{"line":[5,7],"on":["n3"],"txt":"Deuxième lecture : 80. Chaque requête voit l'état validé à son démarrage. REPEATABLE READ figerait 100 ; SERIALIZABLE empêche aussi les anomalies de concurrence."}],"en":{"tab":"Isolation levels","steps":["PostgreSQL uses READ COMMITTED by default: you never see uncommitted data.","First read of the balance inside the transaction: 100.","Meanwhile another transaction changes the balance and commits.","Second read: 80. Each statement sees the committed state when it starts. REPEATABLE READ would freeze 100; SERIALIZABLE also prevents concurrency anomalies."]}},{"id":"q_deadlock","sec":"SQL / PostgreSQL","lvl":"s","xl":1,"tab":"Deadlock","file":"virements.sql","code":["-- T1 : virement de A vers B      -- T2 : virement de B vers A","UPDATE compte ... WHERE id = 'A';  UPDATE compte ... WHERE id = 'B';","UPDATE compte ... WHERE id = 'B';  UPDATE compte ... WHERE id = 'A';","-- ERROR: deadlock detected","","-- ✅ toujours verrouiller dans le même ordre (id croissant)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"T1 verrouille A","s":"","tf":"T1 verrouille A","sf":"","te":"T1 locks A","se":"","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"T2 verrouille B","s":"","tf":"T2 verrouille B","sf":"","te":"T2 locks B","se":"","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"T1 attend B, T2 attend A","s":"cycle : deadlock","tf":"T1 attend B, T2 attend A","sf":"cycle : deadlock","te":"T1 waits B, T2 waits A","se":"cycle: deadlock","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Même ordre (A puis B)","s":"plus de cycle","tf":"Même ordre (A puis B)","sf":"plus de cycle","te":"Same order (A then B)","se":"no more cycle","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[2],"on":["n0"],"txt":"T1 commence par verrouiller la ligne A."},{"line":[2],"on":["n1"],"txt":"En même temps, T2 verrouille la ligne B."},{"line":[3,4],"on":[],"bad":["n2"],"txt":"T1 veut B (tenue par T2) et T2 veut A (tenue par T1) : chacun attend l'autre. PostgreSQL détecte le cycle et annule une des deux."},{"line":[6],"on":["n3"],"txt":"Si les deux transactions verrouillent toujours dans le même ordre (par id), le cycle est impossible. Garder les transactions courtes aide aussi."}],"en":{"tab":"Deadlock","steps":["T1 starts by locking row A.","At the same time, T2 locks row B.","T1 wants B (held by T2) and T2 wants A (held by T1): each waits for the other. PostgreSQL detects the cycle and aborts one.","If both transactions always lock in the same order (by id), the cycle cannot happen. Keeping transactions short helps too."]}},{"id":"q_mvcc","sec":"SQL / PostgreSQL","lvl":"s","xl":1,"tab":"MVCC et VACUUM","file":"mvcc.sql","code":["UPDATE produit SET prix = 12 WHERE id = 1;","-- ligne v1 (prix 10) : conservée pour les lectures en cours","-- ligne v2 (prix 12) : nouvelle version","","-- autovacuum : supprime v1 quand plus personne n'en a besoin","VACUUM (VERBOSE) produit;"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"UPDATE","s":"n'écrase pas la ligne","tf":"UPDATE","sf":"n'écrase pas la ligne","te":"UPDATE","se":"does not overwrite the row","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"v1 (ancienne)","s":"encore lue par d'autres","tf":"v1 (ancienne)","sf":"encore lue par d'autres","te":"v1 (old)","se":"still read by others","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"v2 (nouvelle)","s":"visible après commit","tf":"v2 (nouvelle)","sf":"visible après commit","te":"v2 (new)","se":"visible after commit","at":1},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"VACUUM","s":"récupère l'espace de v1","tf":"VACUUM","sf":"récupère l'espace de v1","te":"VACUUM","se":"reclaims v1's space","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":1},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Avec MVCC, un UPDATE ne modifie pas la ligne sur place : il crée une nouvelle version."},{"line":[2,3],"on":["n1","n2"],"txt":"L'ancienne version reste pour les transactions qui l'ont commencée à lire : les lecteurs ne bloquent pas les écrivains."},{"line":[2],"on":[],"bad":["n1"],"txt":"Une fois que plus personne n'en a besoin, v1 devient une ligne morte qui occupe de la place."},{"line":[5,6],"on":["n3"],"txt":"(auto)VACUUM nettoie ces lignes mortes. Sans lui, tables et index gonflent et les requêtes ralentissent."}],"en":{"tab":"MVCC and VACUUM","steps":["With MVCC, an UPDATE does not change the row in place: it creates a new version.","The old version stays for transactions already reading it: readers do not block writers.","Once nobody needs it, v1 becomes a dead row taking up space.","(auto)VACUUM cleans these dead rows. Without it, tables and indexes bloat and queries slow down."]}},{"id":"q_cte","sec":"SQL / PostgreSQL","lvl":"c","xl":1,"tab":"CTE récursive","file":"categories.sql","code":["WITH RECURSIVE arbre AS (","  SELECT id, nom, parent_id, 1 AS niveau","  FROM categorie WHERE parent_id IS NULL      -- racine","  UNION ALL","  SELECT c.id, c.nom, c.parent_id, a.niveau + 1","  FROM categorie c JOIN arbre a ON c.parent_id = a.id",")","SELECT * FROM arbre ORDER BY niveau;"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Partie de départ","s":"la racine","tf":"Partie de départ","sf":"la racine","te":"Anchor","se":"the root","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Partie récursive","s":"enfants des lignes trouvées","tf":"Partie récursive","sf":"enfants des lignes trouvées","te":"Recursive part","se":"children of found rows","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Répétition","s":"niveau 2, 3, …","tf":"Répétition","sf":"niveau 2, 3, …","te":"Repeat","se":"level 2, 3, …","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Fin","s":"plus aucun enfant","tf":"Fin","sf":"plus aucun enfant","te":"End","se":"no more children","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2,3],"on":["n0"],"txt":"La première partie sélectionne le point de départ : les catégories sans parent."},{"line":[5,6],"on":["n1"],"txt":"La partie récursive joint la table aux lignes déjà trouvées pour obtenir leurs enfants."},{"line":[5,6],"on":["n2"],"txt":"PostgreSQL répète l'opération avec les nouveaux enfants : petits-enfants, puis arrière-petits-enfants…"},{"line":[8],"on":["n3"],"txt":"Quand une étape ne trouve plus personne, la récursion s'arrête. Toute la hiérarchie arrive en une seule requête."}],"en":{"tab":"Recursive CTE","steps":["The first part selects the starting point: categories without a parent.","The recursive part joins the table to rows already found to get their children.","PostgreSQL repeats with the new children: grandchildren, then great-grandchildren…","When a step finds nobody, recursion stops. The whole hierarchy arrives in one query."]}},{"id":"q_pagination","sec":"SQL / PostgreSQL","lvl":"s","xl":1,"tab":"Pagination par clé","file":"pagination.sql","code":["-- ❌ page 5001 : la base lit puis jette 100 000 lignes","SELECT * FROM facture ORDER BY id OFFSET 100000 LIMIT 20;","","-- ✅ pagination par clé (keyset)","SELECT * FROM facture WHERE id > :dernier_id","ORDER BY id LIMIT 20;"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"OFFSET 100 000","s":"lit 100 020 lignes","tf":"OFFSET 100 000","sf":"lit 100 020 lignes","te":"OFFSET 100,000","se":"reads 100,020 rows","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Jette 100 000","s":"garde 20","tf":"Jette 100 000","sf":"garde 20","te":"Discards 100,000","se":"keeps 20","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"WHERE id > dernier","s":"saut direct dans l'index","tf":"WHERE id > dernier","sf":"saut direct dans l'index","te":"WHERE id > last","se":"direct jump in the index","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"20 lignes lues","s":"temps constant","tf":"20 lignes lues","sf":"temps constant","te":"20 rows read","se":"constant time","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Avec OFFSET, la base doit parcourir toutes les lignes sautées."},{"line":[2],"on":[],"bad":["n1"],"txt":"Plus la page est loin, plus c'est lent : page 1 instantanée, page 5001 très lente."},{"line":[5,6],"on":["n2"],"txt":"La pagination par clé repart du dernier id affiché : l'index la place directement au bon endroit."},{"line":[6],"on":["n3"],"txt":"Seules 20 lignes sont lues, quelle que soit la page. Limite : on va de page en page, sans sauter directement à la page 5001."}],"en":{"tab":"Keyset pagination","steps":["With OFFSET, the database must walk every skipped row.","The further the page, the slower: page 1 is instant, page 5001 very slow.","Keyset pagination resumes from the last id shown: the index jumps straight to the right place.","Only 20 rows are read, whatever the page. Limit: you move page by page, not jump straight to page 5001."]}},{"id":"a_onpush","sec":"Angular","lvl":"c","xl":1,"tab":"OnPush et immutabilité","file":"liste.component.ts","code":["@Component({ changeDetection: ChangeDetectionStrategy.OnPush })","export class ListeComponent { @Input() clients!: Client[]; }","","// parent","this.clients.push(nouveau);             // ❌ même référence","this.clients = [...this.clients, nouveau]; // ✅ nouvelle référence"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"OnPush","s":"ne vérifie pas à chaque fois","tf":"OnPush","sf":"ne vérifie pas à chaque fois","te":"OnPush","se":"does not check every time","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"push() dans le tableau","s":"même référence : ignoré","tf":"push() dans le tableau","sf":"même référence : ignoré","te":"push() into the array","se":"same reference: ignored","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Nouveau tableau","s":"nouvelle référence","tf":"Nouveau tableau","sf":"nouvelle référence","te":"New array","se":"new reference","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Composant revérifié","s":"l'écran se met à jour","tf":"Composant revérifié","sf":"l'écran se met à jour","te":"Component re-checked","se":"the screen updates","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Avec OnPush, Angular ne revérifie le composant que dans certains cas, ce qui économise beaucoup de travail."},{"line":[5],"on":[],"bad":["n1"],"txt":"Modifier le tableau sur place (push) garde la même référence : Angular ne voit pas le changement."},{"line":[6],"on":["n2","n3"],"txt":"Créer un nouveau tableau change la référence de l'@Input : le composant est revérifié."},{"line":[1],"on":["n3"],"txt":"Autres déclencheurs : un événement dans le composant, l'async pipe, ou un signal lu dans le template qui change."}],"en":{"tab":"OnPush and immutability","steps":["With OnPush, Angular only re-checks the component in specific cases, which saves a lot of work.","Changing the array in place (push) keeps the same reference: Angular does not see the change.","Creating a new array changes the @Input reference: the component is re-checked.","Other triggers: an event inside the component, the async pipe, or a signal read in the template that changes."]}},{"id":"a_computed","sec":"Angular","lvl":"c","xl":1,"tab":"computed et effect","file":"panier.component.ts","code":["articles = signal<Article[]>([]);","total = computed(() =>","  this.articles().reduce((s, a) => s + a.prix, 0));","","constructor() {","  effect(() => localStorage.setItem('panier', JSON.stringify(this.articles())));","}"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"signal articles","s":"source","tf":"signal articles","sf":"source","te":"articles signal","se":"source","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"computed total","s":"valeur dérivée, en cache","tf":"computed total","sf":"valeur dérivée, en cache","te":"computed total","se":"derived value, cached","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"effect","s":"effet de bord","tf":"effect","sf":"effet de bord","te":"effect","se":"side effect","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"localStorage","s":"sauvegarde","tf":"localStorage","sf":"sauvegarde","te":"localStorage","se":"saved","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1],"on":["n0"],"txt":"articles est un signal : une valeur qui prévient quand elle change."},{"line":[2,3],"on":["n0","n1"],"txt":"computed calcule total à partir d'articles. Il est mis en cache et recalculé seulement si articles change."},{"line":[5,6],"on":["n2","n3"],"txt":"effect sert aux effets de bord : ici, sauvegarder le panier à chaque modification."},{"line":[6],"on":[],"txt":"Règle : pour obtenir une valeur → computed (lecture seule). Pour agir sur l'extérieur → effect. Éviter de modifier d'autres signals dans un effect."}],"en":{"tab":"computed and effect","steps":["articles is a signal: a value that notifies when it changes.","computed derives total from articles. It is cached and recalculated only when articles changes.","effect is for side effects: here, saving the cart on every change.","Rule: to get a value → computed (read-only). To act on the outside world → effect. Avoid setting other signals in an effect."]}},{"id":"a_defer","sec":"Angular","lvl":"c","xl":1,"tab":"@defer","file":"tableau-bord.component.html","code":["<app-resume />","","@defer (on viewport) {","  <app-graphique-ventes />   <!-- bundle séparé -->","} @placeholder {","  <div class=\"zone-vide\"></div>","} @loading {","  <app-spinner />","}"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Page chargée","s":"sans le graphique","tf":"Page chargée","sf":"sans le graphique","te":"Page loaded","se":"without the chart","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"@placeholder","s":"zone réservée","tf":"@placeholder","sf":"zone réservée","te":"@placeholder","se":"reserved area","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Visible à l'écran","s":"déclencheur on viewport","tf":"Visible à l'écran","sf":"déclencheur on viewport","te":"On screen","se":"on viewport trigger","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Chunk téléchargé","s":"graphique affiché","tf":"Chunk téléchargé","sf":"graphique affiché","te":"Chunk downloaded","se":"chart displayed","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"La page s'affiche d'abord avec son contenu léger."},{"line":[5,6],"on":["n1"],"txt":"À la place du graphique, Angular montre le @placeholder."},{"line":[3],"on":["n2"],"txt":"Quand la zone arrive à l'écran, le déclencheur on viewport télécharge le code du graphique (un fichier séparé), avec @loading pendant l'attente."},{"line":[4],"on":["n3"],"txt":"Le bundle initial est plus léger : la page s'ouvre plus vite. Autres déclencheurs : on interaction, on idle, on timer."}],"en":{"tab":"@defer","steps":["The page first renders with its light content.","Instead of the chart, Angular shows the @placeholder.","When the area scrolls into view, the on viewport trigger downloads the chart's code (a separate file), with @loading meanwhile.","The initial bundle is lighter: the page opens faster. Other triggers: on interaction, on idle, on timer."]}},{"id":"a_zoneless","sec":"Angular","lvl":"s","xl":1,"tab":"Sans zone.js","file":"app.config.ts","code":["export const appConfig: ApplicationConfig = {","  providers: [provideZonelessChangeDetection()]","};","","// la vue se met à jour quand :","compteur.set(compteur() + 1);   // un signal change","// ou un événement du template, ou l'async pipe"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"zone.js","s":"patche setTimeout, promesses…","tf":"zone.js","sf":"patche setTimeout, promesses…","te":"zone.js","se":"patches setTimeout, promises…","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Sans zone.js","s":"plus de patch global","tf":"Sans zone.js","sf":"plus de patch global","te":"Without zone.js","se":"no global patching","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Signal modifié","s":"notifie Angular","tf":"Signal modifié","sf":"notifie Angular","te":"Signal changed","se":"notifies Angular","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Vérification ciblée","s":"moins de travail","tf":"Vérification ciblée","sf":"moins de travail","te":"Targeted check","se":"less work","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Avec zone.js, Angular est prévenu après chaque setTimeout, promesse ou événement, et vérifie souvent toute l'application."},{"line":[1,2,3],"on":["n1"],"txt":"En mode zoneless, ce patch global disparaît : moins de code chargé et des traces d'erreur plus lisibles."},{"line":[6],"on":["n2"],"txt":"Angular réagit aux notifications explicites : un signal qui change, un événement du template, l'async pipe."},{"line":[7],"on":["n3"],"txt":"Résultat : moins de vérifications inutiles. Condition : écrire l'état avec des signals (ou markForCheck) plutôt que muter des variables en silence."}],"en":{"tab":"Zoneless","steps":["With zone.js, Angular is notified after every setTimeout, promise or event, and often checks the whole app.","In zoneless mode, this global patching disappears: less code loaded and clearer stack traces.","Angular reacts to explicit notifications: a changing signal, a template event, the async pipe.","Result: fewer useless checks. Requirement: keep state in signals (or call markForCheck) instead of silently mutating fields."]}},{"id":"a_ssr","sec":"Angular","lvl":"s","xl":1,"tab":"SSR et hydratation","file":"app.config.ts","code":["providers: [provideClientHydration()]","","// 1. le serveur rend le HTML complet","// 2. le navigateur l'affiche tout de suite","// 3. Angular se charge et réutilise ce DOM (hydratation)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Serveur","s":"rend le HTML complet","tf":"Serveur","sf":"rend le HTML complet","te":"Server","se":"renders full HTML","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Navigateur","s":"affiche immédiatement","tf":"Navigateur","sf":"affiche immédiatement","te":"Browser","se":"displays immediately","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"JavaScript chargé","s":"Angular démarre","tf":"JavaScript chargé","sf":"Angular démarre","te":"JavaScript loaded","se":"Angular starts","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Hydratation","s":"réutilise le DOM existant","tf":"Hydratation","sf":"réutilise le DOM existant","te":"Hydration","se":"reuses the existing DOM","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[3],"on":["n0"],"txt":"Avec le SSR, le serveur exécute Angular et envoie une page HTML déjà remplie."},{"line":[4],"on":["n1"],"txt":"Le visiteur voit le contenu tout de suite, et les moteurs de recherche peuvent le lire (SEO)."},{"line":[5],"on":["n2"],"txt":"Ensuite, le JavaScript arrive et Angular démarre dans le navigateur."},{"line":[1,5],"on":["n3"],"txt":"L'hydratation rattache les composants au HTML existant au lieu de tout effacer et redessiner : pas de clignotement, page interactive plus vite."}],"en":{"tab":"SSR and hydration","steps":["With SSR, the server runs Angular and sends an already filled HTML page.","The visitor sees the content immediately, and search engines can read it (SEO).","Then the JavaScript arrives and Angular starts in the browser.","Hydration attaches components to the existing HTML instead of wiping and redrawing it: no flicker, interactive sooner."]}},{"id":"a_trackby","sec":"Angular","lvl":"c","xl":1,"tab":"track dans @for","file":"clients.component.html","code":["@for (client of clients(); track client.id) {","  <app-carte-client [client]=\"client\" />","} @empty {","  <p>Aucun client</p>","}"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Liste rechargée","s":"nouveaux objets","tf":"Liste rechargée","sf":"nouveaux objets","te":"List reloaded","se":"new objects","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"track client.id","s":"reconnaît chaque élément","tf":"track client.id","sf":"reconnaît chaque élément","te":"track client.id","se":"recognises each item","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Éléments inchangés","s":"DOM réutilisé","tf":"Éléments inchangés","sf":"DOM réutilisé","te":"Unchanged items","se":"DOM reused","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Seuls les nouveaux","s":"sont créés","tf":"Seuls les nouveaux","sf":"sont créés","te":"Only new ones","se":"are created","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Après un rechargement, la liste contient de nouveaux objets, même si les clients sont les mêmes."},{"line":[1],"on":["n1"],"txt":"track client.id dit à Angular comment reconnaître un élément d'une liste à l'autre."},{"line":[2],"on":["n2"],"txt":"Les clients déjà affichés gardent leur DOM et leur état (champ saisi, animation)."},{"line":[1,3,4],"on":["n3"],"txt":"Seuls les éléments ajoutés ou retirés touchent le DOM : la liste reste fluide, même longue. @empty gère la liste vide."}],"en":{"tab":"track in @for","steps":["After a reload, the list holds new objects, even if the clients are the same.","track client.id tells Angular how to recognise an item from one list to the next.","Clients already shown keep their DOM and state (typed input, animation).","Only added or removed items touch the DOM: the list stays smooth, even when long. @empty handles the empty list."]}},{"id":"a_state","sec":"Angular","lvl":"s","xl":1,"tab":"Gestion d'état","file":"clients.store.ts","code":["export const ClientsStore = signalStore(","  withState({ clients: [] as Client[], chargement: false }),","  withMethods((store, api = inject(ClientApi)) => ({","    async charger() { patchState(store, { chargement: true });","      patchState(store, { clients: await api.liste(), chargement: false }); }","  }))",");"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Composants","s":"lisent le store","tf":"Composants","sf":"lisent le store","te":"Components","se":"read the store","at":1},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Store","s":"état unique","tf":"Store","sf":"état unique","te":"Store","se":"single state","at":0},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Méthodes / actions","s":"seul chemin pour modifier","tf":"Méthodes / actions","sf":"seul chemin pour modifier","te":"Methods / actions","se":"only way to change","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"API","s":"données chargées","tf":"API","sf":"données chargées","te":"API","se":"data loaded","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":0},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[1,2],"on":["n1"],"txt":"L'état partagé (clients, chargement) vit à un seul endroit : le store."},{"line":[2],"on":["n0","n1"],"txt":"Les composants lisent cet état ; plusieurs écrans voient toujours les mêmes données."},{"line":[3,4,5],"on":["n2","n3"],"txt":"Pour le modifier, on passe par les méthodes (ou les actions avec NgRx) : on sait toujours qui change quoi."},{"line":[1],"on":[],"txt":"Plus facile à déboguer et à tester dans une grosse application. Pour une petite, un service avec des signals suffit."}],"en":{"tab":"State management","steps":["Shared state (clients, loading) lives in one place: the store.","Components read this state; several screens always see the same data.","To change it, go through the methods (or actions with NgRx): you always know who changes what.","Easier to debug and test in a large application. For a small one, a service with signals is enough."]}},{"id":"r_exhaust","sec":"RxJS","lvl":"c","xl":1,"tab":"exhaustMap","file":"paiement.component.ts","code":["clicsPayer$.pipe(","  exhaustMap(() => this.api.payer(this.panier))",").subscribe(recu => this.afficher(recu));","","// switchMap  : annule la requête en cours","// exhaustMap : ignore les clics tant qu'elle n'est pas finie"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"1er clic","s":"lance le paiement","tf":"1er clic","sf":"lance le paiement","te":"1st click","se":"starts the payment","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Requête en cours","s":"…","tf":"Requête en cours","sf":"…","te":"Request running","se":"…","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"2e et 3e clics","s":"ignorés","tf":"2e et 3e clics","sf":"ignorés","te":"2nd and 3rd clicks","se":"ignored","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Réponse reçue","s":"nouveaux clics acceptés","tf":"Réponse reçue","sf":"nouveaux clics acceptés","te":"Response received","se":"new clicks accepted","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Premier clic : exhaustMap lance la requête de paiement."},{"line":[2],"on":["n1"],"txt":"Tant que la requête n'est pas terminée, exhaustMap est « occupé »."},{"line":[6],"on":[],"bad":["n2"],"txt":"Les clics suivants sont simplement ignorés : pas de double paiement. switchMap, lui, annulerait la requête en cours."},{"line":[3],"on":["n3"],"txt":"Une fois la réponse reçue, un nouveau clic est de nouveau pris en compte. Idéal pour connexion, paiement, envoi de formulaire."}],"en":{"tab":"exhaustMap","steps":["First click: exhaustMap starts the payment request.","While the request is running, exhaustMap is \"busy\".","The next clicks are simply ignored: no double payment. switchMap would cancel the running request.","Once the response arrives, a new click is accepted again. Ideal for login, payment, form submission."]}},{"id":"r_concat","sec":"RxJS","lvl":"c","xl":1,"tab":"concatMap","file":"editeur.component.ts","code":["modifications$.pipe(","  concatMap(m => this.api.sauvegarder(m))",").subscribe();","","// m1 → sauvegarde 1 terminée → m2 → sauvegarde 2 → m3 …"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"m1, m2, m3","s":"modifications rapides","tf":"m1, m2, m3","sf":"modifications rapides","te":"m1, m2, m3","se":"fast edits","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"File d'attente","s":"dans l'ordre","tf":"File d'attente","sf":"dans l'ordre","te":"Queue","se":"in order","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Sauvegarde 1","s":"terminée avant la 2","tf":"Sauvegarde 1","sf":"terminée avant la 2","te":"Save 1","se":"finished before 2","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Aucune perte","s":"ordre garanti","tf":"Aucune perte","sf":"ordre garanti","te":"Nothing lost","se":"order guaranteed","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"L'utilisateur fait trois modifications coup sur coup."},{"line":[2],"on":["n1"],"txt":"concatMap les met en file : il attend la fin d'une sauvegarde avant de lancer la suivante."},{"line":[5],"on":["n2"],"txt":"La sauvegarde de m2 ne peut donc jamais arriver avant celle de m1."},{"line":[2],"on":["n3"],"txt":"Rien n'est perdu ni annulé. switchMap annulerait, exhaustMap ignorerait, mergeMap lancerait tout en parallèle sans ordre."}],"en":{"tab":"concatMap","steps":["The user makes three edits in a row.","concatMap queues them: it waits for one save to finish before starting the next.","So m2's save can never arrive before m1's.","Nothing is lost or cancelled. switchMap would cancel, exhaustMap would ignore, mergeMap would run everything in parallel without order."]}},{"id":"r_share","sec":"RxJS","lvl":"s","xl":1,"tab":"shareReplay","file":"pays.service.ts","code":["readonly pays$ = this.http.get<Pays[]>('/api/pays').pipe(","  shareReplay({ bufferSize: 1, refCount: true })",");","","// 3 composants : pays$ | async  → 1 seule requête HTTP"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"http.get","s":"observable froid","tf":"http.get","sf":"observable froid","te":"http.get","se":"cold observable","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Sans partage","s":"3 abonnés = 3 requêtes","tf":"Sans partage","sf":"3 abonnés = 3 requêtes","te":"Without sharing","se":"3 subscribers = 3 requests","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"shareReplay(1)","s":"exécution partagée","tf":"shareReplay(1)","sf":"exécution partagée","te":"shareReplay(1)","se":"shared execution","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Nouveaux abonnés","s":"reçoivent la dernière valeur","tf":"Nouveaux abonnés","sf":"reçoivent la dernière valeur","te":"New subscribers","se":"get the last value","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Un observable HTTP est froid : chaque abonnement relance la requête."},{"line":[5],"on":[],"bad":["n1"],"txt":"Trois composants qui s'abonnent provoquent donc trois appels identiques."},{"line":[2],"on":["n2"],"txt":"shareReplay partage une seule exécution entre tous les abonnés."},{"line":[2,5],"on":["n3"],"txt":"Il garde la dernière valeur et la rejoue aux abonnés suivants. refCount: true libère l'abonnement quand plus personne n'écoute."}],"en":{"tab":"shareReplay","steps":["An HTTP observable is cold: each subscription restarts the request.","Three subscribing components therefore trigger three identical calls.","shareReplay shares a single execution among all subscribers.","It keeps the last value and replays it to later subscribers. refCount: true releases the subscription when nobody listens anymore."]}},{"id":"r_combine","sec":"RxJS","lvl":"c","xl":1,"tab":"combineLatest","file":"factures.component.ts","code":["factures$ = combineLatest([this.filtre$, this.page$]).pipe(","  switchMap(([filtre, page]) => this.api.chercher(filtre, page))",");","","// filtre$ : 'payées' ……… 'en retard'","// page$   : …… 1 ……… 2"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"filtre$","s":"1re valeur","tf":"filtre$","sf":"1re valeur","te":"filter$","se":"1st value","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"page$","s":"1re valeur","tf":"page$","sf":"1re valeur","te":"page$","se":"1st value","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"combineLatest","s":"[filtre, page]","tf":"combineLatest","sf":"[filtre, page]","te":"combineLatest","se":"[filter, page]","at":1},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Chaque changement","s":"réémet la combinaison","tf":"Chaque changement","sf":"réémet la combinaison","te":"Each change","se":"re-emits the combination","at":2}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":1},{"id":"e2","d":"M180 208V230","at":2}],"steps":[{"line":[5],"on":["n0"],"txt":"filtre$ émet une première valeur, mais combineLatest attend encore."},{"line":[1,6],"on":["n1","n2"],"txt":"Dès que page$ a aussi émis, combineLatest émet [filtre, page]."},{"line":[2],"on":["n3"],"txt":"Ensuite, chaque nouvelle valeur de l'un ou de l'autre réémet la combinaison avec la dernière valeur de l'autre."},{"line":[1],"on":[],"txt":"Si une source n'émet jamais, rien ne sort : donner une valeur de départ (startWith). forkJoin, lui, attend que toutes les sources soient terminées."}],"en":{"tab":"combineLatest","steps":["filter$ emits a first value, but combineLatest still waits.","As soon as page$ has also emitted, combineLatest emits [filter, page].","Then every new value from either one re-emits the combination with the other's latest value.","If a source never emits, nothing comes out: give it a start value (startWith). forkJoin waits for all sources to complete."]}},{"id":"r_backoff","sec":"RxJS","lvl":"s","xl":1,"tab":"Retry avec délai","file":"api.service.ts","code":["this.http.get('/api/stock').pipe(","  retry({ count: 3, delay: (err, i) => timer(i * 1000) }),","  catchError(() => of(STOCK_VIDE))",");","// échec → 1 s → échec → 2 s → échec → 3 s → échec → repli"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Échec","s":"erreur réseau","tf":"Échec","sf":"erreur réseau","te":"Failure","se":"network error","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Tentative 1","s":"après 1 s","tf":"Tentative 1","sf":"après 1 s","te":"Attempt 1","se":"after 1 s","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Tentatives 2 et 3","s":"après 2 s, puis 3 s","tf":"Tentatives 2 et 3","sf":"après 2 s, puis 3 s","te":"Attempts 2 and 3","se":"after 2 s, then 3 s","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"catchError","s":"valeur de repli","tf":"catchError","sf":"valeur de repli","te":"catchError","se":"fallback value","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"La requête échoue (réseau instable, serveur surchargé)."},{"line":[2],"on":["n1"],"txt":"retry relance la requête après un délai calculé : 1 seconde pour la 1re tentative."},{"line":[2,5],"on":["n2"],"txt":"Le délai grandit à chaque essai : on laisse au serveur le temps de récupérer au lieu de le bombarder."},{"line":[3],"on":["n3"],"txt":"Après 3 échecs, catchError fournit une valeur de repli. Ne réessayer que les erreurs temporaires et les requêtes idempotentes (GET)."}],"en":{"tab":"Retry with backoff","steps":["The request fails (unstable network, overloaded server).","retry re-runs the request after a computed delay: 1 second for the first attempt.","The delay grows with each try: the server gets time to recover instead of being hammered.","After 3 failures, catchError provides a fallback value. Only retry transient errors and idempotent requests (GET)."]}},{"id":"d_multistage","sec":"REST, Git, Docker","lvl":"c","xl":1,"tab":"Build multi-étapes","file":"Dockerfile","code":["FROM maven:3.9-eclipse-temurin-21 AS build","WORKDIR /app","COPY . .","RUN mvn -q package -DskipTests","","FROM eclipse-temurin:21-jre","COPY --from=build /app/target/app.jar /app.jar","ENTRYPOINT [\"java\", \"-jar\", \"/app.jar\"]"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Étape build","s":"Maven + JDK + sources","tf":"Étape build","sf":"Maven + JDK + sources","te":"Build stage","se":"Maven + JDK + sources","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"mvn package","s":"produit app.jar","tf":"mvn package","sf":"produit app.jar","te":"mvn package","se":"produces app.jar","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Étape finale","s":"JRE seul","tf":"Étape finale","sf":"JRE seul","te":"Final stage","se":"JRE only","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Image finale","s":"petite, moins de failles","tf":"Image finale","sf":"petite, moins de failles","te":"Final image","se":"small, fewer vulnerabilities","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2,3],"on":["n0"],"txt":"La première étape utilise une image Maven avec le JDK et copie les sources."},{"line":[4],"on":["n1"],"txt":"Elle compile et produit le JAR."},{"line":[6,7],"on":["n2"],"txt":"La deuxième étape part d'une image JRE légère et ne copie que le JAR."},{"line":[8],"on":["n3"],"txt":"Maven, le JDK et les sources ne sont pas dans l'image finale : elle est plusieurs fois plus petite et expose moins de failles."}],"en":{"tab":"Multi-stage build","steps":["The first stage uses a Maven image with the JDK and copies the sources.","It compiles and produces the JAR.","The second stage starts from a light JRE image and copies only the JAR.","Maven, the JDK and the sources are not in the final image: it is several times smaller and exposes fewer vulnerabilities."]}},{"id":"d_versioning","sec":"REST, Git, Docker","lvl":"c","xl":1,"tab":"Versionner une API","file":"ClientController.java","code":["@GetMapping(\"/api/v1/clients/{id}\")   // { \"nom\": \"Ben Ali Ahmed\" }","ClientV1 lireV1(@PathVariable Long id) { ... }","","@GetMapping(\"/api/v2/clients/{id}\")   // { \"prenom\": \"Ahmed\", \"nom\": \"Ben Ali\" }","ClientV2 lireV2(@PathVariable Long id) { ... }","","// v1 : en-tête Deprecation + date de fin annoncée"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Clients existants","s":"utilisent la v1","tf":"Clients existants","sf":"utilisent la v1","te":"Existing clients","se":"use v1","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Nouveau format","s":"incompatible","tf":"Nouveau format","sf":"incompatible","te":"New format","se":"breaking","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"/api/v2","s":"publiée à côté","tf":"/api/v2","sf":"publiée à côté","te":"/api/v2","se":"published alongside","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Fin de la v1","s":"annoncée, puis retirée","tf":"Fin de la v1","sf":"annoncée, puis retirée","te":"End of v1","se":"announced, then removed","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1,2],"on":["n0"],"txt":"Des applications utilisent déjà /api/v1 avec un champ nom unique."},{"line":[4],"on":[],"bad":["n1"],"txt":"Séparer prénom et nom casserait ces applications si on modifiait la v1."},{"line":[4,5],"on":["n2"],"txt":"On publie une v2 à côté : les nouveaux clients l'utilisent, les anciens continuent avec la v1."},{"line":[7],"on":["n3"],"txt":"On annonce une date de fin pour la v1, puis on la retire. Ajouter un champ optionnel, lui, ne demande pas de nouvelle version."}],"en":{"tab":"API versioning","steps":["Applications already use /api/v1 with a single name field.","Splitting first and last name would break them if v1 were changed.","Publish a v2 alongside: new clients use it, old ones keep v1.","Announce an end date for v1, then remove it. Adding an optional field does not need a new version."]}},{"id":"d_bluegreen","sec":"REST, Git, Docker","lvl":"s","xl":1,"tab":"Déploiement blue-green","file":"deploiement.txt","code":["blue  (v1.4)  ← 100 % du trafic","green (v1.5)  déployée, testée, 0 % du trafic","","load balancer : blue → green   (bascule)","","problème ? load balancer : green → blue  (retour en quelques secondes)"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Blue (v1.4)","s":"sert les utilisateurs","tf":"Blue (v1.4)","sf":"sert les utilisateurs","te":"Blue (v1.4)","se":"serves users","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Green (v1.5)","s":"déployée et testée","tf":"Green (v1.5)","sf":"déployée et testée","te":"Green (v1.5)","se":"deployed and tested","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Bascule","s":"le trafic passe sur green","tf":"Bascule","sf":"le trafic passe sur green","te":"Switch","se":"traffic moves to green","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Retour arrière","s":"immédiat vers blue","tf":"Retour arrière","sf":"immédiat vers blue","te":"Rollback","se":"instant back to blue","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"L'environnement blue sert tous les utilisateurs avec la version actuelle."},{"line":[2],"on":["n1"],"txt":"On déploie la nouvelle version sur green, identique, et on la teste sans impacter personne."},{"line":[4],"on":["n2"],"txt":"Le load balancer bascule tout le trafic vers green d'un coup : pas d'interruption."},{"line":[6],"on":["n3"],"txt":"En cas de problème, on rebascule vers blue en quelques secondes. Point d'attention : la base de données doit rester compatible avec les deux versions."}],"en":{"tab":"Blue-green deployment","steps":["The blue environment serves all users with the current version.","Deploy the new version to green, an identical environment, and test it without affecting anyone.","The load balancer switches all traffic to green at once: no downtime.","If something breaks, switch back to blue in seconds. Watch out: the database must stay compatible with both versions."]}},{"id":"d_saga","sec":"REST, Git, Docker","lvl":"s","xl":1,"tab":"Saga","file":"saga.txt","code":["1. Commande : créée (en attente)","2. Stock     : réservé","3. Paiement  : REFUSÉ","","compensations, dans l'ordre inverse :","2'. Stock    : réservation annulée","1'. Commande : annulée"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Commande créée","s":"transaction locale","tf":"Commande créée","sf":"transaction locale","te":"Order created","se":"local transaction","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Stock réservé","s":"transaction locale","tf":"Stock réservé","sf":"transaction locale","te":"Stock reserved","se":"local transaction","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Paiement refusé","s":"échec","tf":"Paiement refusé","sf":"échec","te":"Payment refused","se":"failure","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Compensations","s":"stock libéré, commande annulée","tf":"Compensations","sf":"stock libéré, commande annulée","te":"Compensations","se":"stock released, order cancelled","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Chaque service a sa propre base : une transaction unique sur tous n'est pas possible."},{"line":[1,2],"on":["n0","n1"],"txt":"La saga enchaîne des transactions locales : le service commande crée la commande, puis le service stock réserve les articles."},{"line":[3],"on":[],"bad":["n2"],"txt":"Le paiement est refusé : les étapes déjà validées ne peuvent pas être « rollbackées »."},{"line":[5,6,7],"on":["n3"],"txt":"On exécute des actions de compensation dans l'ordre inverse : libérer le stock, annuler la commande. Orchestrée par un coordinateur ou par événements."}],"en":{"tab":"Saga","steps":["Each service has its own database: one transaction across all of them is not possible.","The saga chains local transactions: the order service creates the order, then the stock service reserves the items.","The payment is refused: the steps already committed cannot be rolled back.","Compensating actions run in reverse order: release the stock, cancel the order. Driven by an orchestrator or by events."]}},{"id":"d_cherry","sec":"REST, Git, Docker","lvl":"c","xl":1,"tab":"cherry-pick","file":"terminal","code":["git switch develop","git log --oneline     # a1b2c3d  fix: arrondi TVA","","git switch main","git cherry-pick a1b2c3d","git push origin main"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"develop","s":"correctif + autres travaux","tf":"develop","sf":"correctif + autres travaux","te":"develop","se":"fix + other work","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Commit a1b2c3d","s":"le correctif seul","tf":"Commit a1b2c3d","sf":"le correctif seul","te":"Commit a1b2c3d","se":"the fix alone","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"cherry-pick sur main","s":"copie ce commit","tf":"cherry-pick sur main","sf":"copie ce commit","te":"cherry-pick on main","se":"copies that commit","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"main","s":"correctif sans le reste","tf":"main","sf":"correctif sans le reste","te":"main","se":"fix without the rest","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"develop contient le correctif, mais aussi des fonctionnalités pas encore prêtes."},{"line":[2],"on":["n1"],"txt":"On repère l'identifiant du commit du correctif."},{"line":[4,5],"on":["n2"],"txt":"Sur main, git cherry-pick applique uniquement ce commit (avec un nouvel identifiant)."},{"line":[6],"on":["n3"],"txt":"La production reçoit le correctif sans le reste de develop. Un merge aurait tout apporté."}],"en":{"tab":"cherry-pick","steps":["develop holds the fix, but also features that are not ready yet.","Find the fix commit's identifier.","On main, git cherry-pick applies only that commit (with a new identifier).","Production gets the fix without the rest of develop. A merge would have brought everything."]}},{"id":"d_healthcheck","sec":"REST, Git, Docker","lvl":"s","xl":1,"tab":"Probes et healthcheck","file":"deployment.yaml","code":["readinessProbe:","  httpGet: { path: /actuator/health/readiness, port: 8080 }","livenessProbe:","  httpGet: { path: /actuator/health/liveness, port: 8080 }","","# management.endpoint.health.probes.enabled=true"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Démarrage","s":"cache en chargement","tf":"Démarrage","sf":"cache en chargement","te":"Startup","se":"cache loading","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Readiness KO","s":"retiré du trafic","tf":"Readiness KO","sf":"retiré du trafic","te":"Readiness fails","se":"removed from traffic","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Readiness OK","s":"reçoit les requêtes","tf":"Readiness OK","sf":"reçoit les requêtes","te":"Readiness OK","se":"receives requests","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Liveness KO","s":"pod redémarré","tf":"Liveness KO","sf":"pod redémarré","te":"Liveness fails","se":"pod restarted","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[6],"on":["n0"],"txt":"Spring Boot expose deux contrôles via Actuator : readiness et liveness."},{"line":[1,2],"on":[],"bad":["n1"],"txt":"Au démarrage (ou si la base est indisponible), readiness échoue : Kubernetes n'envoie pas de trafic à ce pod."},{"line":[2],"on":["n2"],"txt":"Dès que readiness répond OK, le pod reçoit les requêtes."},{"line":[3,4],"on":[],"bad":["n3"],"txt":"Si l'application est bloquée, liveness échoue : Kubernetes redémarre le conteneur. Ne pas tester la base dans liveness, sinon une panne de base redémarre tout."}],"en":{"tab":"Probes and healthcheck","steps":["Spring Boot exposes two checks through Actuator: readiness and liveness.","At startup (or if the database is down), readiness fails: Kubernetes sends no traffic to this pod.","As soon as readiness reports OK, the pod receives requests.","If the app is stuck, liveness fails: Kubernetes restarts the container. Don't check the database in liveness, or a database outage restarts everything."]}},{"id":"d_rate","sec":"REST, Git, Docker","lvl":"s","xl":1,"tab":"Limitation de débit","file":"RateLimitFilter.java","code":["if (!bucket.tryConsume(1)) {      // ex. 100 requêtes / minute","  response.setStatus(429);","  response.setHeader(\"Retry-After\", \"30\");","  return;","}","chain.doFilter(request, response);"],"vb":[360,312],"nodes":[{"id":"n0","x":20,"y":16,"w":320,"h":48,"t":"Requête","s":"jeton disponible ?","tf":"Requête","sf":"jeton disponible ?","te":"Request","se":"token available?","at":0},{"id":"n1","x":20,"y":88,"w":320,"h":48,"t":"Oui","s":"traitée normalement","tf":"Oui","sf":"traitée normalement","te":"Yes","se":"processed normally","at":1},{"id":"n2","x":20,"y":160,"w":320,"h":48,"t":"Non","s":"429 Too Many Requests","tf":"Non","sf":"429 Too Many Requests","te":"No","se":"429 Too Many Requests","at":2},{"id":"n3","x":20,"y":232,"w":320,"h":48,"t":"Retry-After: 30","s":"le client attend 30 s","tf":"Retry-After: 30","sf":"le client attend 30 s","te":"Retry-After: 30","se":"client waits 30 s","at":3}],"edges":[{"id":"e0","d":"M180 64V86","at":1},{"id":"e1","d":"M180 136V158","at":2},{"id":"e2","d":"M180 208V230","at":3}],"steps":[{"line":[1],"on":["n0"],"txt":"Chaque client dispose d'un quota, par exemple 100 requêtes par minute (algorithme du seau à jetons)."},{"line":[6],"on":["n1"],"txt":"S'il reste un jeton, la requête est traitée."},{"line":[2],"on":[],"bad":["n2"],"txt":"Quota dépassé : on répond 429 Too Many Requests, le code prévu pour ce cas."},{"line":[3],"on":["n3"],"txt":"Retry-After indique quand réessayer. 503 signifie que le serveur est indisponible, 403 un accès interdit : ce n'est pas la même chose."}],"en":{"tab":"Rate limiting","steps":["Each client has a quota, e.g. 100 requests per minute (token bucket algorithm).","If a token is left, the request is processed.","Quota exceeded: reply 429 Too Many Requests, the status made for this case.","Retry-After says when to retry. 503 means the server is unavailable, 403 means access denied: not the same thing."]}}];
(function(){
  const maxQ = {}; SC.forEach(s=>{ maxQ[s.sec]=Math.max(maxQ[s.sec]||0,s.q); });
  const LANGF = {"Java":"Java","Spring Boot":"Spring Boot","JPA / Hibernate":"JPA","SQL / PostgreSQL":"SQL","Angular":"Angular","RxJS":"RxJS","REST, Git, Docker":"DevOps"};
  EXPL.forEach(e=>{
    LVL[e.id]=e.lvl; EN[e.id]=e.en;
    maxQ[e.sec]=(maxQ[e.sec]||0)+1;
    SC.push({id:e.id, sec:e.sec, q:maxQ[e.sec], tab:e.tab, xl:1, file:e.file, lang:LANGF[e.sec]||e.sec, vb:e.vb, code:e.code, nodes:e.nodes, edges:e.edges, steps:e.steps});
  });
})();
let curSec = SC[cur].sec;
const ICO={"Java":["java"],"Spring Boot":["spring"],"JPA / Hibernate":["hibernate"],"Angular":["angular"],"RxJS":["rxjs"],"SQL / PostgreSQL":["pg"],"REST, Git, Docker":["git","docker"]};
const icoHtml=s=>(ICO[s]||[]).map(k=>'<i class="ti i-'+k+'" aria-hidden="true"></i>').join('');
function buildSecs(){
  const nav=$("secs"); nav.innerHTML="";
  [...new Set(SC.map(s=>s.sec))].forEach(sec=>{
    const b=document.createElement("button"); b.type="button"; b.innerHTML=icoHtml(sec); b.appendChild(document.createTextNode(sec));
    b.setAttribute("aria-selected", sec===curSec?"true":"false");
    b.addEventListener("click",()=>{curSec=sec; buildSecs(); const list=qList(); select(list[0]);});
    nav.appendChild(b);
  });
}
let lvlF = new URLSearchParams(location.search).get("niveau") || lsGet("ent_lvl") || "all";
if (!["all","j","c","s"].includes(lvlF)) lvlF = "all";
const inLvl = i => lvlF==="all" || lvOf(SC[i])===lvlF;
function qList(){ return SC.map((s,i)=>i).filter(i=>SC[i].sec===curSec && inLvl(i)).sort((a,b)=>SC[a].q-SC[b].q); }
function buildLvls(){
  const nav=$("lvls"); if(!nav) return;
  const T=LVLT[lang==="en"?"en":"fr"], cnt=l=>SC.filter(s=>l==="all"||lvOf(s)===l).length;
  nav.setAttribute("aria-label", lang==="en"?"Level":"Niveau");
  nav.innerHTML='<span class="lvls-lab">'+(lang==="en"?"Level":"Niveau")+'</span>'+["all","j","c","s"].map(l=>'<button type="button" data-lvlf="'+l+'" aria-pressed="'+(l===lvlF)+'">'+(l==="all"?(lang==="en"?"All levels":"Tous les niveaux"):'<span class="lvl lvl-'+l+'">'+T[l]+'</span>')+'<small>'+cnt(l)+'</small></button>').join("");
  nav.querySelectorAll("[data-lvlf]").forEach(b=>b.addEventListener("click",()=>{ lvlF=b.dataset.lvlf; lsSet("ent_lvl",lvlF); buildLvls(); if(!inLvl(cur)){ const l=qList(); select(l[0]); } else { buildQs(); } }));
}
function buildQs(){
  const nav=$("qs"); nav.innerHTML="";
  qList().forEach(i=>{
    const b=document.createElement("button"); b.type="button"; const lv=lvOf(SC[i]); b.innerHTML='<span class="ld lvl-'+lv+'" aria-hidden="true"></span>'; b.appendChild(document.createTextNode(SC[i].q+". "+TAB(SC[i]))); b.title=LVLT[lang==="en"?"en":"fr"][lv];
    b.setAttribute("aria-selected", i===cur?"true":"false");
    b.addEventListener("click",()=>select(i));
    nav.appendChild(b);
  });
}
function select(i){
  stop(); cur=i; step=0; curSec=SC[i].sec;
  buildQs(); build(); render();
}
function build(){
  const s = SC[cur]; if (s.xl) s.nodes.forEach(n=>{ n.t=lang==="en"?n.te:n.tf; n.s=lang==="en"?n.se:n.sf; });
  codeEl.classList.toggle("wrap", false);
  svg.setAttribute("viewBox","0 0 "+s.vb[0]+" "+s.vb[1]);
  svg.setAttribute("aria-label",U().schema+TAB(s));
  svg.innerHTML=""; els={};
  const defs = mk("defs",{});
  [["def","mk-def"],["on","mk-on"],["bad","mk-bad"]].forEach(([n,c])=>{
    const m = mk("marker",{id:"m-"+n,viewBox:"0 0 10 10",refX:"9",refY:"5",markerWidth:"6",markerHeight:"6",orient:"auto-start-reverse"});
    m.appendChild(mk("path",{d:"M0 0L10 5L0 10z","class":c}));
    defs.appendChild(m);
  });
  svg.appendChild(defs);
  s.edges.forEach(e=>{
    const p = mk("path",{d:e.d,"class":"e","marker-end":"url(#m-def)"});
    svg.appendChild(p); els[e.id]={el:p,def:e,kind:"e"};
  });
  (s.texts||[]).forEach(x=>{const t=mk("text",{"class":"tl",x:x.x,y:x.y}); t.textContent=x.t; svg.appendChild(t);});
  s.nodes.forEach(n=>{
    const g = mk("g",{"class":"n"+(n.cls?" "+n.cls:"")});
    g.appendChild(mk("rect",{x:n.x,y:n.y,width:n.w,height:n.h,rx:"8"}));
    const t = mk("text",{"class":"t",x:n.x+n.w/2,"text-anchor":"middle"});
    const st = mk("text",{"class":"s",x:n.x+n.w/2,"text-anchor":"middle",y:n.y+n.h/2+13});
    g.appendChild(t); g.appendChild(st); svg.appendChild(g);
    els[n.id]={el:g,def:n,kind:"n",t,st};
  });
  $("fname").textContent=s.file; $("flang").innerHTML=lvBadge(s)+'<span class="fl"></span>'; $("flang").lastChild.textContent=s.lang;
  codeEl.innerHTML = s.code.map((l,i)=>'<div class="ln" data-l="'+(i+1)+'"><span class="no">'+(i+1)+'</span><span class="src">'+(hl(l)||" ")+'</span></div>').join("");
  const dots=$("dots"); dots.innerHTML=s.steps.map(()=>"<span></span>").join("");
}

function render(){
  const s = SC[cur], st = s.steps[step];
  const lab = {};
  for (let k=0;k<=step;k++) Object.assign(lab, s.steps[k].lab||{});
  const on = new Set(st.on||[]), bad = new Set(st.bad||[]);
  for (const id in els){
    const o = els[id], d = o.def;
    const vis = (d.at||0) <= step && step <= (d.until ?? 99);
    const state = bad.has(id) ? "bad" : on.has(id) ? "on" : "";
    if (o.kind==="e"){
      o.el.setAttribute("class","e"+(state?" "+state:"")+(vis?"":" hid"));
      o.el.setAttribute("marker-end","url(#m-"+(state||"def")+")");
    } else {
      o.el.setAttribute("class","n"+(d.cls?" "+d.cls:"")+(state?" "+state:"")+(vis?"":" hid"));
      const tt = lab[id] ?? d.t, ss = lab[id+".s"] ?? (d.s||"");
      o.t.textContent = tt; o.st.textContent = ss;
      fit(o.t, d.w-12); fit(o.st, d.w-12);
      if (d.top){ o.t.setAttribute("y", d.y+18); o.st.setAttribute("y", d.y+32); }
      else o.t.setAttribute("y", ss ? d.y+d.h/2-3 : d.y+d.h/2+4);
    }
  }
  const lines = new Set(st.line||[]);
  let first = null;
  codeEl.querySelectorAll(".ln").forEach(el=>{
    const isCur = lines.has(+el.dataset.l);
    el.classList.toggle("cur", isCur);
    if (isCur && !first) first = el;
  });
  if (first){
    const top = first.offsetTop - codeEl.clientHeight/3;
    codeEl.scrollTo({top:Math.max(0,top),behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto":"smooth"});
  }
  $("txt").textContent = TXT(s,step);
  if (window.a11ySpeak) window.a11ySpeak(U().step(step+1,s.steps.length)+". "+TXT(s,step));
  $("stepno").innerHTML = lvBadge(s)+'<span></span>'; $("stepno").lastChild.textContent = U().step(step+1,s.steps.length)+(lines.size?U().line(lines.size)+[...lines].join(", "):"");
  $("prev").disabled = step===0;
  $("next").disabled = step===s.steps.length-1;
  [...$("dots").children].forEach((d,i)=>d.className = i===step ? "now" : i<step ? "done" : "");
}

function go(d){
  const n = SC[cur].steps.length;
  const ns = Math.min(n-1, Math.max(0, step+d));
  if (ns!==step){ step=ns; render(); }
}
function stop(){ if(timer){clearInterval(timer);timer=null;} $("play").textContent=U().play; }
function play(){
  if (timer){ stop(); return; }
  if (step===SC[cur].steps.length-1){ step=0; render(); }
  $("play").textContent=U().pause;
  timer = setInterval(()=>{
    if (step>=SC[cur].steps.length-1){ stop(); return; }
    go(1);
  }, 3200);
}
$("prev").addEventListener("click",()=>{stop();go(-1);});
$("next").addEventListener("click",()=>{stop();go(1);});
$("play").addEventListener("click",play);
document.addEventListener("keydown",e=>{
  if (e.key==="ArrowRight"){stop();go(1);}
  else if (e.key==="ArrowLeft"){stop();go(-1);}
});
function applyLang(){
  const u=U(); document.documentElement.lang=lang;document.documentElement.setAttribute("data-lang",lang);
  document.title=u.title; $("h1").innerHTML=u.h1; $("lead").textContent=u.lead; $("foot").firstChild.textContent=u.tip;
  $("prev").textContent=u.prev; $("next").textContent=u.next; $("play").textContent=timer?u.pause:u.play;
  $("pdf").textContent=u.pdf; $("quiz").textContent=u.quiz; $("quiz").href="qcm/?lang="+lang; $("back").textContent=u.back;
  document.querySelectorAll("[data-lang]").forEach(b=>b.setAttribute("aria-pressed",b.dataset.lang===lang?"true":"false"));
}
document.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>{lang=b.dataset.lang;lsSet("lang",lang);try{history.replaceState(null,"","?lang="+lang+(SC[cur]?"&q="+SC[cur].id:""))}catch(e){};applyLang();buildLvls();buildQs();build();render();}));
